+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`; the ingredients are consumed with ref `sale:<ticket>` at the
+// time of sale. A ticket is imported once; later imports of it are skipped.
+// Importing is all or nothing (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, listItems, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a sale with this ticket was already imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sales lines { row, ticket, soldAt, dishId, qty } and consumes their
+ * ingredients. Lines of tickets already imported are skipped. Throws (and
+ * changes nothing) naming the row of an unknown dish or where an item runs out.
+ * Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines) {
+  const dishes = lines.map((l) => {
+    try {
+      return getDish(store, l.dishId);
+    } catch {
+      throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    }
+  });
+  const planned = lines
+    .map((l, i) => ({ ...l, uses: scaled(getRecipe(store, dishes[i].recipeId), l.qty).filter((u) => u.qty > 0) }))
+    .filter((l) => !ticketImported(store, l.ticket));
+
+  const need = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const total = round3((need.get(u.itemId) ?? 0) + u.qty);
+      need.set(u.itemId, total);
+      const item = getItem(store, u.itemId);
+      const available = round3(onHand(store, u.itemId));
+      if (available < total)
+        throw new AppError("sale_not_enough_stock", { row: p.row, item: item.name, available, unit: item.unit });
+    }
+  }
+
+  const before = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    for (const p of planned) {
+      for (const u of p.uses) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    }
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+  return { tickets: new Set(planned.map((p) => p.ticket)).size, dishes: planned.reduce((s, p) => s + p.qty, 0) };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement in those days.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.uses) theoretical.set(u.itemId, round3((theoretical.get(u.itemId) ?? 0) + u.qty));
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, round3((actual.get(batch.itemId) ?? 0) + m.qty));
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = theoretical.get(item.id) ?? 0;
+      const a = actual.get(item.id) ?? 0;
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
